onClick:
{{
  (async function() {
    const data = Get_Detail_Intervention.data[0];
    const machineId = data?.ID_Machine;

    if (!machineId) {
      showAlert("Aucune machine rattachée à cette intervention.", "warning");
      return;
    }

    // 1. Mémorisation de l'ID machine et de l'historique de retour
    await storeValue('detail_machine_id', machineId);
    await storeValue('page_precedente', 'Détail Intervention');
    await storeValue('id_precedent', appsmith.URL.queryParams.id);

    // 2. Navigation vers la fiche Détail Matériel
    await navigateTo('Détail Matériel', { id: machineId });
  })()
}}
